import{_ as t,o as a,c as s,ap as d}from"./chunks/framework.Dk4Y1ER6.js";const h=JSON.parse('{"title":"API overview","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md","lastUpdated":null}'),o={name:"api/index.md"};function l(n,e,r,i,c,y){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="api-index" tabindex="-1">API overview <a class="header-anchor" href="#api-index" aria-label="Permalink to &quot;API overview {#api-index}&quot;">​</a></h1><p>The public interface, grouped by theme. Every exported name appears on exactly one of the pages below; the last one is a catch-all that lists anything not yet curated, so a newly exported symbol can never go undocumented.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">Covers</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./bases">Bases</a></td><td style="text-align:left;">basis types, metric, accessors, <code>init_*</code></td></tr><tr><td style="text-align:left;"><a href="./tensors">Tensors</a></td><td style="text-align:left;"><code>AbstractTens</code>, <code>Tens</code>, components, Kelvin-Mandel</td></tr><tr><td style="text-align:left;"><a href="./structured">Structured tensors</a></td><td style="text-align:left;"><code>TensISO</code> and the isotropic projectors</td></tr><tr><td style="text-align:left;"><a href="./walpole">Walpole and orthotropy</a></td><td style="text-align:left;"><code>TensTI</code>, <code>TensOrtho</code>, parametrizations</td></tr><tr><td style="text-align:left;"><a href="./cubic">Cubic symmetry</a></td><td style="text-align:left;"><code>TensCubic</code>, three constants and a cube frame</td></tr><tr><td style="text-align:left;"><a href="./projection">Projection</a></td><td style="text-align:left;"><code>project</code>, <code>best_sym_tens</code>, predicates</td></tr><tr><td style="text-align:left;"><a href="./special">Special tensors</a></td><td style="text-align:left;">Levi-Civita, rotations, unit vectors, random tensors</td></tr><tr><td style="text-align:left;"><a href="./coorsystems">Coordinate systems</a></td><td style="text-align:left;"><code>CoordinateSystem</code>, its exact geometry and the operators</td></tr><tr><td style="text-align:left;"><a href="./coorsystems_num">Numerical coordinate systems</a></td><td style="text-align:left;"><code>PointwiseGeometry</code></td></tr><tr><td style="text-align:left;"><a href="./submanifold">Submanifolds</a></td><td style="text-align:left;"><code>Submanifold</code> and its accessors</td></tr><tr><td style="text-align:left;"><a href="./symbolic">Symbolic helpers</a></td><td style="text-align:left;"><code>tsimplify</code>, <code>tsubs</code>, and the array algebra</td></tr><tr><td style="text-align:left;"><a href="./full_index">Full index</a></td><td style="text-align:left;">everything, alphabetically</td></tr></tbody></table><p><code>divergence</code> is Tensors.jl&#39;s function, extended to the coordinate systems, so that <code>using TensND, Tensors</code> leaves one <code>divergence</code>. The Hessian is <code>hess</code>, not <code>hessian</code>: SymPy, which TensND loads, exports a <code>hessian</code> of its own, and the same name would have made <code>using TensND, SymPyPythonCall</code> ambiguous.</p>',4)])])}const p=t(o,[["render",l]]);export{h as __pageData,p as default};
